links.condition:
if = {
			limit = {
				exists = owner
				owner = { is_twisted_experimenters_empire = yes }
			}

			# Random tech insight
			if = {
				limit = {
					current_situation_approach = situation_experimental_testing_physics
				}
				owner = {
					give_twisted_experimenters_physics_tech_insight = yes
					set_country_flag = twisted_experimenters_physics_tech_insight_received
				}
			}
			else_if = {
				limit = {
					current_situation_approach = situation_experimental_testing_society
				}
				owner = {
					give_twisted_experimenters_society_tech_insight = yes
					set_country_flag = twisted_experimenters_society_tech_insight_received
				}
			}
			else_if = {
				limit = {
					current_situation_approach = situation_experimental_testing_engineering
				}
				owner = {
					give_twisted_experimenters_engineering_tech_insight = yes
					set_country_flag = twisted_experimenters_engineering_tech_insight_received
				}
			}

			owner = {
				# Test Subjects death
				if = {
					limit = {
						NOT = { has_country_flag = this_is_the_part_where_we_kill_you }
					}
					if = {
						limit = {
							check_variable_arithmetic = {
								which = value:count_killed_test_subjects
								value > 999
							}
						}
						set_country_flag = this_is_the_part_where_we_kill_you
					}
				}
				every_owned_pop_job = {
					limit = {
						OR = {
							has_job_type = test_subject
							has_job_type = test_subject_drone
						}
					}
					sacrifice_assigned_pop_amount = {
						percentage = value:test_subjects_loss_percent
					}
				}

				# Choose next cycle
				country_event = {
					id = shroud.1015
				}
			}
		}

