script:
carrier_event = {
	id = shroud.1105
	title = shroud.1105.title
	desc = {
		trigger = {
			text = shroud.1105.desc.intro
			text = newline
			if = {
				limit = {
					owner = { has_country_flag = test_subjects_escaped }
				}
				text = shroud.1105.desc.escaped
			}
			else = {
				text = shroud.1105.desc.outro
			}
		}
	}

	is_triggered_only = yes
	picture = GFX_evt_experimental_testing
	show_sound = event_dig_site

	location = root

	trigger = {
		exists = owner
		owner = {
			is_twisted_experimenters_empire = yes
		}
	}

	immediate = {
		owner = {
			set_timed_country_flag = {
				flag = test_subjects_escaped_recently
				days = 3600
			}
			set_country_flag = test_subjects_escaped
		}
	}

	option = {
		name = shroud.1105.a
		allow = {
			custom_tooltip = {
				fail_text = shroud_is_homicidal
				owner = { is_homicidal = no }
			}
		}
		custom_tooltip = shroud.1105.a.tt
		owner = {
			add_monthly_resource_mult = {
				resource = unity
				value = @tier3unityreward
				min = @tier3unitymin
				max = @tier3unitymax
			}
		}
		hidden_effect = {
			every_owned_pop_job = {
				limit = {
					OR = {
						has_job_type = test_subject
						has_job_type = test_subject_drone
					}
				}
				every_job_pop_group = {
					limit = {
						pop_group_size > 1
					}
					# Save the pop group as an event target
					save_event_target_as = old_pop_group
					# Save their species as an event target
					species = {
						save_event_target_as = old_species
					}
					# If a modified species hasn't been created, create one
					# and save them as an event target
					if = {
						limit = {
							NOT = {
								any_galaxy_species = {
									has_species_flag = refugee_species_of_species@event_target:old_species
									has_species_flag = refugee_species_of_empire@root.owner
								}
							}
						}
						create_species = {
							is_mod = yes
							name = this
							plural = this
							class = this
							portrait = this
							traits = this
							can_be_modified = this
							homeworld = this
							namelist = this
							gender = this
							effect = {
								modify_species = {
									species = this
									change_scoped_species = no

									effect = {
										set_species_flag = refugee_species_of_species@event_target:old_species
										set_species_flag = refugee_species_of_empire@root.owner
										save_event_target_as = target_species
									}
								}
							}
						}
					}
					# If a modified species does exist, save them as the event target
					else = {
						random_galaxy_species = {
							limit = {
								has_species_flag = refugee_species_of_species@event_target:old_species
								has_species_flag = refugee_species_of_empire@root.owner
							}
							save_event_target_as = target_species
						}
					}
					# Scope back to the planet
					# Create the empty pop group
					# and move pops into it
					planet = {
						create_pop_group = {
							pop_group = event_target:old_pop_group
							species = event_target:target_species
							size = 0
							effect = {
								transfer_pop_amount = {
									source = event_target:old_pop_group
									target = this
									percentage = 0.5
								}
								save_event_target_as = new_pop_group
							}
						}
					}
					event_target:new_pop_group = {
						if = {
							limit = {
								exists = owner
								is_valid_refugee_pop = yes
							}
							save_event_target_as = refugee_pop #Must be saved for refugee_pop_effect to work
							refugee_pop_effect = yes
						}
						else = {
							kill_pop_group = {
								pop_group = this
								percentage = 1
							}
						}
					}
				}
			}
		}
	}

	option = {
		name = shroud.1105.b
		custom_tooltip = shroud.1105.b.tt
		owner = {
			add_modifier = {
				modifier = testing_lockdown
				days = 360
			}
		}
	}

	option = {
		name = shroud.1105.c
		custom_tooltip = shroud.1105.c.tt
		owner = {
			add_modifier = {
				modifier = example_set
			}
		}
		hidden_effect = {
			every_owned_pop_job = {
				limit = {
					OR = {
						has_job_type = test_subject
						has_job_type = test_subject_drone
					}
				}
				kill_assigned_pop_amount = {
					percentage = 1
				}
			}
			owner = {
				set_country_flag = test_subjects_executed
				every_situation = {
					limit = { is_situation_type = situation_experimental_testing }
					situation_event = { id = shroud.1010 }
				}
			}
		}
	}
}

