script:
situation_event = {
	id = shroud.2200
	hide_window = yes
	is_triggered_only = yes

	trigger = {
		OR = {
			AND = {
				has_situation_flag = breach_shroud_stage_1_started
				situation_progress >= @[( breach_shroud_stage_1_end - breach_shroud_start_value ) * 0.3 + breach_shroud_start_value ] # Social event at 33% & Attunement event at 66%
			}
			AND = {
				has_situation_flag = breach_shroud_stage_2_started
				situation_progress >= @[ ( breach_shroud_stage_2_end - breach_shroud_stage_1_end ) * 0.5 + breach_shroud_stage_1_end ] # Attunement event halfway through
			}
			AND = {
				has_situation_flag = breach_shroud_stage_3_started
				situation_progress >= @[ ( breach_shroud_end_value - breach_shroud_stage_2_end ) * 0.5 + breach_shroud_stage_2_end ] # Attunement event halfway through
			}
		}
	}

	immediate = {
		if = {
			limit = {
				has_situation_flag = breach_shroud_stage_1_started
				situation_progress < @[ ( breach_shroud_stage_1_end - breach_shroud_start_value ) * 0.65 + breach_shroud_start_value ]
			}
			if = {
				limit = {
					NOT = { has_situation_flag = breach_shroud_social_event_triggered }
				}
				set_situation_flag = breach_shroud_social_event_triggered
				fire_on_action = {
					on_action = on_breach_the_shroud_situation_random_social_events_list
				}
			}
			break = yes
		}

		# Attunement events (called once per stage)
		remove_situation_flag = breach_shroud_social_event_triggered
		remove_situation_flag = breach_shroud_stage_1_started
		remove_situation_flag = breach_shroud_stage_2_started
		remove_situation_flag = breach_shroud_stage_3_started
		random_list = {
			1 = { # Beneficial events
				modifier = {
					factor = @breach_shroud_approach_mult
					has_situation_flag = beneficial_approach
				}
				fire_on_action = {
					on_action = on_breach_the_shroud_situation_random_beneficial_events_list
				}
			}
			1 = { # Balanced events
				fire_on_action = {
					on_action = on_breach_the_shroud_situation_random_balanced_events_list
				}
			}
			1 = { # Chaotic events
				modifier = {
					factor = @breach_shroud_approach_mult
					has_situation_flag = chaotic_approach
				}
				fire_on_action = {
					on_action = on_breach_the_shroud_situation_random_chaotic_events_list
				}
			}
		}
	}
}

