script:
situation_event = {
	id = shroud.2820
	title = shroud.2820.name
	picture = GFX_evt_shroud_spacemadness
	show_sound = event_endbringers_madness
	is_triggered_only = yes

	desc = {
		trigger = {
			text = shroud.2820.desc.1
			text = newline
			if = {
				limit = {
					owner = {
						num_buildings = { type = building_chamber_of_silence value < 1 }
					}
				}
				text = shroud.2820.desc.2.no_chamber
			}
			else = {
				text = shroud.2820.desc.2.chamber
			}
		}
	}

	situation = this

	trigger = {
		exists = owner
	}

	option = {
		name = {
			trigger = {
				if = {
					limit = {
						owner = {
							num_buildings = { type = building_chamber_of_silence value < 1 }
						}
					}
					text = shroud.2820.a.no_chamber
				}
				else = {
					text = shroud.2820.a.chamber
				}
			}
		}
		if = {
			limit = {
				owner = {
					num_buildings = { type = building_chamber_of_silence value < 1 }
				}
			}
			custom_tooltip = shroud.2820.a.tt_no_chamber
		}
		else = {
			custom_tooltip = shroud.2820.a.tt
		}
	}
}

