script:
situation_event = {
	id = shroud.2830
	title = shroud.2830.name
	picture = GFX_evt_psionics
	show_sound = {
		trigger = { owner = { is_robot_empire = yes } }
		sound = event_psionic_robot
	}
	show_sound = {
		trigger = { owner = { is_robot_empire = no } }
		sound = event_psionic
	}
	is_triggered_only = yes

	situation = this

	desc = {
		trigger = {
			text = shroud.2830.desc
			text = newline
			if = {
				limit = {
					owner = {
						has_tradition = tr_psionics_shroud_great_awakening
					}
				}
				text = shroud.2830.desc.outro.awakening
			}
			else = {
				text = shroud.2830.desc.outro.no_awakening
			}
		}
	}

	immediate = {
		owner = {
			if = {
				limit = { has_tradition = tr_psionics_shroud_great_awakening }
				turn_main_species_to_psionic = yes
				update_node_portraits_if_gestalt_effect = yes
				update_every_leader_from_psionic_countries = yes
				refresh_portraits = character
			}
		}
	}

	option = {
		name = {
			trigger = {
				if = {
					limit = {
						owner = {
							has_tradition = tr_psionics_shroud_great_awakening
						}
					}
					text = shroud.2830.a.awakening
				}
				else = {
					text = shroud.2830.a.no_awakening
				}
			}
		}
		if = {
			limit = {
				owner = {
					has_tradition = tr_psionics_shroud_great_awakening
				}
			}
			custom_tooltip = shroud.2830.a.tt
		}
		else = {
			custom_tooltip = shroud.2830.a.tt_no_awakening
		}
	}
}

