script:
situation_event = {
	id = shroud.2840
	title = shroud.2840.name
	desc = shroud.2840.desc
	picture = GFX_evt_shroudwalker_enclave
	show_sound = {
		trigger = { owner = { is_robot_empire = yes } }
		sound = event_psionic_robot
	}
	show_sound = {
		trigger = { owner = { is_robot_empire = no } }
		sound = event_psionic
	}
	is_triggered_only = yes

	trigger = {
		exists = owner
		owner = {
			has_origin = origin_endbringers
		}
	}

	situation = this

	option = {
		name = shroud.2840.a
		custom_tooltip = situation_breach_shroud_finish_effects
	}

	after = {
		hidden_effect = {
			owner = {
				enable_patron_first_contact_project = {
					name = ENDBRINGERS_COMMUNE_WITH_THE_VOICE
					patron = end_of_the_cycle
					owner = this
				}
				set_country_flag = psionic_traditions_unlocked
				breach_shroud = yes
				open_shroud_tab = yes
			}
		}
		destroy_situation = this
	}
}
